package textfold

import (
	_ "embed"
	"sort"
	"strconv"
	"strings"
	"sync"
)

// unicodeData is generated by testdata/gen.py from the Python that the parity
// fixtures were made with; its first line names that Python and Unicode version.
//
//go:embed unicode.txt
var unicodeData string

type runeRange struct{ lo, hi rune }

type tables struct {
	header    string
	erased    []runeRange     // NFKD holds only combining marks: every fold drops them
	base      map[rune]string // NFKD without combining marks, when it differs from the rune
	lower     map[rune]string // str.lower() of the single rune, when it differs
	space     map[rune]bool   // str.isspace()
	cased     []runeRange     // cased and not case-ignorable
	ignorable []runeRange     // case-ignorable
}

var data = sync.OnceValue(func() *tables { return parseTables(unicodeData) })

// parseTables reads unicode.txt: per line a record kind and its entries,
// "lo-hi" ranges (e, C, I), "cp:cp.cp" mappings (d, l) or code points (s).
func parseTables(text string) *tables {
	t := &tables{base: map[rune]string{}, lower: map[rune]string{}, space: map[rune]bool{}}
	for _, line := range strings.Split(text, "\n") {
		if line == "" {
			continue
		}
		if line[0] == '#' {
			t.header = line
			continue
		}
		f := strings.Fields(line)
		for _, e := range f[1:] {
			switch f[0] {
			case "e":
				t.erased = append(t.erased, parseRange(e))
			case "C":
				t.cased = append(t.cased, parseRange(e))
			case "I":
				t.ignorable = append(t.ignorable, parseRange(e))
			case "d", "l":
				from, to, ok := strings.Cut(e, ":")
				if !ok {
					corrupt(e)
				}
				m := t.base
				if f[0] == "l" {
					m = t.lower
				}
				m[parseRune(from)] = string(parseSeq(to))
			case "s":
				t.space[parseRune(e)] = true
			default:
				corrupt(line)
			}
		}
	}
	return t
}

func corrupt(s string) { panic("textfold: corrupt unicode.txt entry " + strconv.Quote(s)) }

func parseRune(h string) rune {
	v, err := strconv.ParseUint(h, 16, 32)
	if err != nil {
		corrupt(h)
	}
	return rune(v)
}

func parseRange(e string) runeRange {
	lo, hi, ok := strings.Cut(e, "-")
	if !ok {
		corrupt(e)
	}
	return runeRange{parseRune(lo), parseRune(hi)}
}

func parseSeq(e string) []rune {
	parts := strings.Split(e, ".")
	out := make([]rune, len(parts))
	for i, p := range parts {
		out[i] = parseRune(p)
	}
	return out
}

func inRanges(rs []runeRange, r rune) bool {
	i := sort.Search(len(rs), func(i int) bool { return rs[i].hi >= r })
	return i < len(rs) && rs[i].lo <= r
}

const (
	hangulBase  = 0xAC00
	hangulLast  = 0xD7A3
	hangulLBase = 0x1100
	hangulVBase = 0x1161
	hangulTBase = 0x11A7
)

// decompose returns NFKD(r) without its combining marks (ccc != 0), the
// part of a character every fold keeps; ok is false when that is r itself.
func decompose(r rune) (string, bool) {
	if r < 0x80 {
		return "", false
	}
	if r >= hangulBase && r <= hangulLast {
		s := r - hangulBase
		out := []rune{hangulLBase + s/588, hangulVBase + (s%588)/28}
		if s%28 != 0 {
			out = append(out, hangulTBase+s%28)
		}
		return string(out), true
	}
	t := data()
	if b, ok := t.base[r]; ok {
		return b, true
	}
	if inRanges(t.erased, r) {
		return "", true
	}
	return "", false
}

// IsSpace reports Python's str.isspace() for one rune: the separators of str.split().
// It is the one isspace table of the module; pycompat.IsSpace and pycompat.Fields use it.
func IsSpace(r rune) bool {
	switch r {
	case ' ', '\t', '\n', '\v', '\f', '\r', 0x1c, 0x1d, 0x1e, 0x1f:
		return true
	}
	return r >= 0x80 && data().space[r]
}
